const S = v => (v == null ? '' : String(v)).trim();
const N = v => { const n = parseInt(String(v).replace(/[, ]/g,''),10); return isNaN(n)?0:n; };
const vid = u => { const m = String(u||'').match(/shorts\/([\w-]{11})|v=([\w-]{11})|youtu\.be\/([\w-]{11})|\/([\w-]{11})(?:\?|$)/); return m ? (m[1]||m[2]||m[3]||m[4]) : ''; };

// rows (metadata) from the seed node
const rows = $('Load creator data').all().map(i => i.json);

// apify transcript items (handle array-in-one-item or split items)
let ap = $('Apify · YouTube transcripts').all().map(i => i.json);
if (ap.length === 1 && Array.isArray(ap[0])) ap = ap[0];

const TKEYS = ['transcript','transcript_text','transcriptText','text','captions','caption','content'];
const UKEYS = ['url','videoUrl','video_url','videoId','video_id','id'];
const pickText = o => {
  for (const k of TKEYS) if (typeof o[k]==='string' && o[k].trim()) return o[k].trim();
  // else: longest string field > 40 chars
  let best='';
  for (const k in o) if (typeof o[k]==='string' && o[k].length>best.length && o[k].length>40) best=o[k];
  return best.trim();
};
const pickId = o => { for (const k of UKEYS) if (o[k]) { const id=vid(o[k])||S(o[k]); if(id) return id; } return ''; };

const tmap = {};
for (const o of ap) { const id = pickId(o); if (id) tmap[id] = pickText(o); }

const items = rows.map(r => {
  const transcript = tmap[S(r.id)] || null;
  const caption = S(r.caption) || null;
  const hook = (transcript || caption || S(r.title) || '').replace(/\n/g,' ').split('. ')[0].split(' ').slice(0,14).join(' ');
  return { id: S(r.id), platform: S(r.platform), title: S(r.title)||null, transcript, caption, hook,
    published_at: S(r.published_at)||null,
    metrics: { views: N(r.views), likes: N(r.likes), comments: N(r.comments) }, performance_percentile: 0 };
});
const scored = items.map(i => (i.metrics.likes + i.metrics.comments) / Math.max(i.metrics.views,1));
const sorted = [...scored].sort((a,b)=>a-b);
items.forEach((it,k)=>{ const rank = sorted.filter(v=>v<=scored[k]).length; it.performance_percentile = items.length ? Math.round((rank/items.length)*1000)/1000 : 0; });

const corpusDoc = { creator: { handle: S(rows[0]&&rows[0].creator), niche: S(rows[0]&&rows[0].niche), platforms: ['youtube'] }, items };

// compact input for the fingerprint LLM (top items in full, weighted by percentile)
const lines = items.map(i => `- [pct ${i.performance_percentile}] TITLE: ${i.title}\n  TRANSCRIPT: ${i.transcript || '(none)'}`).join('\n');
const fpInput = `CREATOR: ${corpusDoc.creator.handle} | NICHE: ${corpusDoc.creator.niche}\nItems (weight the high-percentile ones most):\n${lines}`;

const withT = items.filter(i=>i.transcript).length;
return [{ json: { corpus: corpusDoc, corpusJson: JSON.stringify(corpusDoc, null, 2), fingerprint_input: fpInput, items_with_transcript: withT, items_total: items.length } }];
